    'myo.sub': 'Besoin d’un bot Discord, d’une app, d’un site — ou de quelque chose de sur mesure comme un audit de sécurité de votre code (CVE / CWE / CVSS) ? Démarrez une consultation payante : vous obtenez un vrai conseil et un devis ferme. On ne crée qu’après validation du devis.',
