    'hs.d.pricing.consolidationDiscount': 'Quand un propriétaire consolide les plusieurs abonnements d’un pool fusionné en un seul plan plus grand, cette fraction (0–0,9, ex. 0,15 = 15 %) est retirée du prix du plan unique. Affichée comme « économies de consolidation » sur ses pools.',
