    'acl.final': "Passé ces {n} jours, c’est irréversible — aucune restauration, et le support ne peut pas ramener le compte. Si tu recrées plus tard un compte avec cette même adresse e-mail, on la reconnaît et on rattache ton historique, y compris ton éventuel dossier de modération ; une autre adresse repart vraiment de zéro.",
