    'ud.cl.mode.final': "Définitive",
    'ud.cl.mode.final.s': "Aucun lien d’annulation envoyé, le compte ne peut pas l’arrêter. Toi, tu peux encore l’annuler d’ici jusqu’à la date.",
    'ud.cl.start.m.final': "DÉFINITIVE : la personne ne peut pas l’annuler — aucun lien d’annulation, seulement le motif, la date et un moyen de nous contacter. Le {d}, tout abonnement actif est résilié et tout ce qui est hébergé sous ce compte — dépôts, catalogues, leur stockage — est supprimé. Rien n’est transféré à personne. Toi, tu peux encore l’annuler jusque-là.",
    'ud.cl.teardown': "La planifier suspend immédiatement ses dépôts, catalogues et éléments — rien n’est supprimé, et l’annuler remet chacun dans l’état où il était. À la date : abonnements résiliés, tout supprimé avec le stockage, pools retirés. Rien n’est transféré — si quelque chose doit survivre, déplace-le vers un autre compte avant.",
